    ppHeadProvider: ["Provider", "Darparwr", "Dostawca", "ਪ੍ਰੋਵਾਈਡਰ", "فراہم کنندہ", "প্রোভাইডার", "પ્રોવાઈડર", "提供商", "Furnizor", "Proveedor", "المزود", "Fornecedor"],
    ppHeadValue: ["Total value", "Cyfanswm gwerth", "Łączna wartość", "ਕੁੱਲ ਮੁੱਲ", "کل قدر", "মোট মূল্য", "કુલ મૂલ્ય", "总价值", "Valoare totală", "Valor total", "القيمة الإجمالية", "Valor total"],
